import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { cause7Schema, type Cause7 } from "./cause7.js";

export type SignalExternalWorkflowExecutionFailedEventAttributes = {
  /** The workflowId of the external workflow execution that the signal was being delivered to. */
  workflowId: string;
  /** The runId of the external workflow execution that the signal was being delivered to. */
  runId?: string;
  /**
   * The cause of the failure. This information is generated by the system and can be useful for
   * diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it
   * lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage
   * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
   */
  cause: Cause7;
  /**
   * The ID of the SignalExternalWorkflowExecutionInitiated event corresponding to the
   * SignalExternalWorkflowExecution decision to request this signal. This information can be useful
   * for diagnosing problems by tracing back the chain of events leading up to this event.
   */
  initiatedEventId: number;
  /**
   * The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in
   * the SignalExternalWorkflowExecution decision for this signal. This information can be useful
   * for diagnosing problems by tracing back the chain of events leading up to this event.
   */
  decisionTaskCompletedEventId: number;
  /**
   * The data attached to the event that the decider can use in subsequent workflow tasks. This data
   * isn't sent to the workflow execution.
   */
  control?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const signalExternalWorkflowExecutionFailedEventAttributesSchema: Schema<SignalExternalWorkflowExecutionFailedEventAttributes> =
  s.object<SignalExternalWorkflowExecutionFailedEventAttributes>(
    {
      workflowId: s.string(),
      runId: s.optional(s.string()),
      cause: cause7Schema,
      initiatedEventId: s.int(),
      decisionTaskCompletedEventId: s.int(),
      control: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
